CREATE TABLE elite_base.body_material_v2 (
    body_id varchar(37) NOT NULL,
    material varchar(255) NOT NULL,
    percent numeric,
    CONSTRAINT body_material_v2_pk PRIMARY KEY (body_id, material)
) PARTITION BY HASH (body_id);

CREATE TABLE elite_base.body_material_v2_p0 PARTITION OF elite_base.body_material_v2 FOR VALUES WITH (MODULUS 40, REMAINDER 0);
